#include "ksStateFactoryServicesTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::StateFactoryServicesTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned seed=0;seed<256;++seed)for(unsigned kind=0;kind<2;++kind)for(unsigned store:{0u,3u}){T task{T::Kind(kind)};std::array<unsigned,256> page{};std::vector<unsigned> services;unsigned reads=0,writes=0,clocks=0;auto read=[&](unsigned offset){check(offset==reads++,"Factory readorder");return uint8_t(seed+offset*17);};auto write=[&](unsigned offset,unsigned value){check(offset==writes++,"Factory writeorder");page[offset]=value;};while(!task.awaitingTail()){if(task.awaitingChild()){services.push_back(unsigned(task.service()));check(task.resumeChild(),"Factory childresume");continue;}unsigned c=task.nextClocks(store),n=reads+writes;check(!task.advanceBefore(c-1,read,write,store)&&n==reads+writes,"Factory earlyeffects");check(task.advanceBefore(c,read,write,store)==c,"Factory admission");clocks+=c;}services.push_back(unsigned(task.service()));check(services==(kind?std::vector<unsigned>{0,1,2,3}:std::vector<unsigned>{0,1}),"Factory serviceorder");check(reads==256*kind&&writes==256*kind,"Factory bytecounts");for(unsigned i=0;i<256&&kind;++i)check(page[i]==uint8_t(seed+i*17),"Factory pagebytes");unsigned expected=kind?119+256*(20+store):35;check(clocks==expected,"Factory clocks");check(task.retireTail()&&task.complete()&&!task.retireTail(),"Factory tailretirement");++cases;}std::cout<<"PASS: "<<cases<<" complete provided/factory services,256latebytecopies/typedstore-load-message-panel/deadlines+clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
